'use strict';

module.exports = function (api) {
  return {
    createcreate(params, callback) {
      return api.post({
        url: '/customers',
        data}, callback);
    },
    editedit(customerId, params, callback) {
      return api.put({
        url: '/customers/' + customerId,
        data}, callback);
    },
    fetchfetch(customerId, callback) {
      return api.get({
        url: '/customers/' + customerId
      }, callback);
    },
    allall() {
      var params = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : {};
      var callback = arguments[1];
      var count = params.count,
          skip = params.skip;


      count = Number(count) || 10;
      skip = Number(skip) || 0;

      return api.get({
        url: '/customers',
        data: {
          count,
          skip}
      }, callback);
    },
    fetchTokensfetchTokens(customerId, callback) {
      return api.get({
        url: '/customers/' + customerId + '/tokens'
      }, callback);
    },
    fetchTokenfetchToken(customerId, tokenId, callback) {
      return api.get({
        url: '/customers/' + customerId + '/tokens/' + tokenId
      }, callback);
    },
    deleteTokendeleteToken(customerId, tokenId, callback) {
      return api.delete({
        url: '/customers/' + customerId + '/tokens/' + tokenId
      }, callback);
    },
    addBankAccountaddBankAccount(customerId, params, callback) {
      return api.post({
        url: '/customers/' + customerId + '/bank_account',
        data}, callback);
    },
    deleteBankAccountdeleteBankAccount(customerId, bankId, callback) {
      return api.delete({
        url: '/customers/' + customerId + '/bank_account/' + bankId
      }, callback);
    },
    requestEligibilityCheckrequestEligibilityCheck(params, callback) {
      return api.post({
        url: '/customers/eligibility',
        data}, callback);
    },
    fetchEligibilityfetchEligibility(eligibilityId, callback) {
      return api.get({
        url: '/customers/eligibility/' + eligibilityId
      }, callback);
    }
  };
};

